def pre(vals):
    return True


def expected_running_peak(vals):
    out = []
    has_best = False
    best = 0

    for v in vals:
        if has_best:
            if v > best:
                best = v
        else:
            best = v
            has_best = True

        out.append(best)

    return out


def post(vals, result):
    return result == expected_running_peak(vals)
